create extension if not exists pgcrypto;
create table if not exists public.leads (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, name text not null, business_name text, phone text, email text, website text, business_type text not null default 'other' check (business_type in ('gymos','website_development','curakart','other')), status text not null default 'new' check (status in ('new','contacted','interested','proposal','negotiation','won','lost')), source text, notes text, estimated_value numeric(12,2), next_follow_up_at timestamptz, last_contacted_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.clients (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, lead_id uuid references public.leads(id) on delete set null, name text not null, business_name text, phone text, email text, business_type text not null default 'other' check (business_type in ('gymos','website_development','curakart','other')), lifecycle_status text not null default 'onboarding' check (lifecycle_status in ('onboarding','active','paused','completed','churned')), contract_value numeric(12,2), payment_status text not null default 'not_invoiced' check (payment_status in ('not_invoiced','pending','part_paid','paid','overdue')), notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.activities (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, lead_id uuid references public.leads(id) on delete cascade, client_id uuid references public.clients(id) on delete cascade, channel text not null check (channel in ('email','whatsapp','phone','ai_voice','meeting','note','system')), direction text not null default 'internal' check (direction in ('inbound','outbound','internal')), subject text, body text, outcome text, occurred_at timestamptz not null default now(), created_at timestamptz not null default now(), check (lead_id is not null or client_id is not null));
create table if not exists public.tasks (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, lead_id uuid references public.leads(id) on delete cascade, client_id uuid references public.clients(id) on delete cascade, title text not null, description text, due_at timestamptz, completed_at timestamptz, source text not null default 'manual' check (source in ('manual','ai_suggested','automation')), created_at timestamptz not null default now());
create table if not exists public.communication_preferences (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, lead_id uuid references public.leads(id) on delete cascade, client_id uuid references public.clients(id) on delete cascade, channel text not null check (channel in ('phone','ai_voice','whatsapp','email')), consent_status text not null default 'unknown' check (consent_status in ('unknown','consented','opted_out','not_applicable')), consent_source text, consent_recorded_at timestamptz, do_not_contact boolean not null default false, created_at timestamptz not null default now(), check (lead_id is not null or client_id is not null), unique nulls not distinct (owner_id,lead_id,client_id,channel));
create table if not exists public.agent_actions (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, lead_id uuid references public.leads(id) on delete set null, client_id uuid references public.clients(id) on delete set null, action_type text not null, payload jsonb not null default '{}'::jsonb, approval_status text not null default 'pending_approval' check (approval_status in ('draft','pending_approval','approved','sent','rejected','cancelled')), approved_at timestamptz, executed_at timestamptz, result jsonb, created_at timestamptz not null default now());
create table if not exists public.agent_runs (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, agent_name text not null, trigger_source text not null default 'user', status text not null default 'queued' check (status in ('queued','running','succeeded','failed','cancelled')), input jsonb not null default '{}'::jsonb, output jsonb, error_message text, started_at timestamptz, finished_at timestamptz, created_at timestamptz not null default now());
create table if not exists public.call_logs (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, lead_id uuid references public.leads(id) on delete set null, client_id uuid references public.clients(id) on delete set null, provider text, call_type text not null check (call_type in ('human','ai_voice')), status text not null default 'scheduled', consent_checked boolean not null default false, started_at timestamptz, ended_at timestamptz, duration_seconds integer, summary text, recording_url text, created_at timestamptz not null default now());
create index if not exists leads_owner_status_idx on public.leads(owner_id,status);
create index if not exists leads_follow_up_idx on public.leads(owner_id,next_follow_up_at);
create index if not exists clients_owner_status_idx on public.clients(owner_id,lifecycle_status);
create index if not exists tasks_due_idx on public.tasks(owner_id,due_at) where completed_at is null;
create index if not exists activities_lead_time_idx on public.activities(lead_id,occurred_at desc);
create index if not exists agent_actions_approval_idx on public.agent_actions(owner_id,approval_status,created_at desc);
do $$ declare t text; begin foreach t in array array['leads','clients','activities','tasks','communication_preferences','agent_actions','agent_runs','call_logs'] loop execute format('alter table public.%I enable row level security',t); execute format('create policy %I on public.%I for all to authenticated using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()))',t||'_owner_all',t); end loop; end $$;
grant select,insert,update,delete on public.leads,public.clients,public.activities,public.tasks,public.communication_preferences,public.agent_actions,public.agent_runs,public.call_logs to authenticated;